-- Export-only catalog; does not contain player data.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID(N'dbo.game_content',N'U') IS NULL
CREATE TABLE [game_content] ([category] nvarchar(120) COLLATE Latin1_General_100_BIN2 NOT NULL, [item_key] nvarchar(120) COLLATE Latin1_General_100_BIN2 NOT NULL, [payload] nvarchar(max) NOT NULL, PRIMARY KEY ([category],[item_key]));
IF OBJECT_ID(N'dbo.game_content_links',N'U') IS NULL
CREATE TABLE [game_content_links] ([category] nvarchar(120) COLLATE Latin1_General_100_BIN2 NOT NULL, [item_key] nvarchar(120) COLLATE Latin1_General_100_BIN2 NOT NULL, [relation] nvarchar(120) COLLATE Latin1_General_100_BIN2 NOT NULL, [target_category] nvarchar(120) COLLATE Latin1_General_100_BIN2 NOT NULL, [target_key] nvarchar(120) COLLATE Latin1_General_100_BIN2 NOT NULL, PRIMARY KEY ([category],[item_key],[relation]), FOREIGN KEY ([category],[item_key]) REFERENCES [game_content]([category],[item_key]), FOREIGN KEY ([target_category],[target_key]) REFERENCES [game_content]([category],[item_key]));
DELETE FROM game_content_links;
DELETE FROM game_content;
COMMIT;
